// HubServiceHandler is an implementation of the hub.v1.HubService service.
type HubServiceHandler interface {
	// Validates a manifest and its contracts without saving.
	ValidateProduct(context.Context, *connect.Request[v1.ValidateProductRequest]) (*connect.Response[v1.ValidateProductResponse], error)
	// Registers a new version of a Data Product and its Contracts.
	RegisterProduct(context.Context, *connect.Request[v1.RegisterProductRequest]) (*connect.Response[v1.RegisterProductResponse], error)
	// Retrieves a specific product and its resolved contracts.
	GetProduct(context.Context, *connect.Request[v1.GetProductRequest]) (*connect.Response[v1.GetProductResponse], error)
	// Retrieves the physical BigQuery schema and configuration for a product port.
	GetProductSchema(context.Context, *connect.Request[v1.GetProductSchemaRequest]) (*connect.Response[v1.GetProductSchemaResponse], error)
	// Retrieves a specific contract.
	GetContract(context.Context, *connect.Request[v1.GetContractRequest]) (*connect.Response[v1.GetContractResponse], error)
	// Lists available contracts.
	ListContracts(context.Context, *connect.Request[v1.ListContractsRequest]) (*connect.Response[v1.ListContractsResponse], error)
	// Ping verifies connectivity to the Hub.
	Ping(context.Context, *connect.Request[v1.PingRequest]) (*connect.Response[v1.PingResponse], error)
	// Validates a data payload against a specific contract version.
	ValidateSchema(context.Context, *connect.Request[v1.ValidateSchemaRequest]) (*connect.Response[v1.ValidateSchemaResponse], error)
	// Deletes a specific product version (used primarily for smoke testing/cleanup).
	DeleteProduct(context.Context, *connect.Request[v1.DeleteProductRequest]) (*connect.Response[v1.DeleteProductResponse], error)
	// Resolves a Port URN to its definition and parent product.
	ResolvePort(context.Context, *connect.Request[v1.ResolvePortRequest]) (*connect.Response[v1.ResolvePortResponse], error)
	// Analyzes the impact of a proposed contract change on downstream consumers.
	CheckDownstreamImpact(context.Context, *connect.Request[v1.CheckDownstreamImpactRequest]) (*connect.Response[v1.CheckDownstreamImpactResponse], error)
	// Registers a new Entity definition.
	RegisterEntity(context.Context, *connect.Request[v1.RegisterEntityRequest]) (*connect.Response[v1.RegisterEntityResponse], error)
	// Retrieves an Entity by namespace.
	GetEntity(context.Context, *connect.Request[v1.GetEntityRequest]) (*connect.Response[v1.GetEntityResponse], error)
	// Lists all registered Entities.
	ListEntities(context.Context, *connect.Request[v1.ListEntitiesRequest]) (*connect.Response[v1.ListEntitiesResponse], error)
	// Analyzes the impact of a proposed Entity change on contracts and products.
	CheckEntityImpact(context.Context, *connect.Request[v1.CheckEntityImpactRequest]) (*connect.Response[v1.CheckEntityImpactResponse], error)
	// Deletes a specific Entity (used for testing).
	DeleteEntity(context.Context, *connect.Request[v1.DeleteEntityRequest]) (*connect.Response[v1.DeleteEntityResponse], error)
	// Registers a new Team (or updates members if existing).
	RegisterTeam(context.Context, *connect.Request[v1.RegisterTeamRequest]) (*connect.Response[v1.RegisterTeamResponse], error)
	// Retrieves a Team by name.
	GetTeam(context.Context, *connect.Request[v1.GetTeamRequest]) (*connect.Response[v1.GetTeamResponse], error)
	// Lists all registered Teams.
	ListTeams(context.Context, *connect.Request[v1.ListTeamsRequest]) (*connect.Response[v1.ListTeamsResponse], error)
	// Registers a new Data Contract version.
	RegisterContract(context.Context, *connect.Request[v1.RegisterContractRequest]) (*connect.Response[v1.RegisterContractResponse], error)
	// Lists all registered Data Products.
	ListProducts(context.Context, *connect.Request[v1.ListProductsRequest]) (*connect.Response[v1.ListProductsResponse], error)
	// Manually triggers Dataplex synchronization for a product.
	SyncProduct(context.Context, *connect.Request[v1.SyncProductRequest]) (*connect.Response[v1.SyncProductResponse], error)
	// Records the result of an SLA/Quality audit run.
	RecordAuditRun(context.Context, *connect.Request[v1.RecordAuditRunRequest]) (*connect.Response[v1.RecordAuditRunResponse], error)
	// Retrieves the audit history for a specific product.
	ListAuditRuns(context.Context, *connect.Request[v1.ListAuditRunsRequest]) (*connect.Response[v1.ListAuditRunsResponse], error)
	// SendAlert triggers a manual or automated alert.
	SendAlert(context.Context, *connect.Request[v1.SendAlertRequest]) (*connect.Response[v1.SendAlertResponse], error)
	// Analyzes the impact of a DTO field change on downstream assets.
	AnalyzeImpact(context.Context, *connect.Request[v1.AnalyzeImpactRequest]) (*connect.Response[v1.AnalyzeImpactResponse], error)
	// Subscribe registers a new subscriber or updates an existing one for a Data Product.
	Subscribe(context.Context, *connect.Request[v1.SubscribeRequest]) (*connect.Response[v1.SubscribeResponse], error)
	// Unsubscribe removes a subscriber from a Data Product.
	Unsubscribe(context.Context, *connect.Request[v1.UnsubscribeRequest]) (*connect.Response[v1.UnsubscribeResponse], error)
	// ListSubscriptions retrieves all subscribers for a specific Data Product.
	ListSubscriptions(context.Context, *connect.Request[v1.ListSubscriptionsRequest]) (*connect.Response[v1.ListSubscriptionsResponse], error)
	// IngestEvent records a platform event and triggers relevant alerts.
	IngestEvent(context.Context, *connect.Request[v1.IngestEventRequest]) (*connect.Response[v1.IngestEventResponse], error)
	// ExtractDSARPlan generates a plan for Data Subject Access Requests (DSAR).
	// It identifies all physical locations where a specific entity's data may reside.
	ExtractDSARPlan(context.Context, *connect.Request[v1.ExtractDSARPlanRequest]) (*connect.Response[v1.ExtractDSARPlanResponse], error)
	// ReportAnomaly reports a health degradation or recovery for a product or contract.
	ReportAnomaly(context.Context, *connect.Request[v1.ReportAnomalyRequest]) (*connect.Response[v1.ReportAnomalyResponse], error)
	// GetHealth retrieves the current health status of a product or contract.
	GetHealth(context.Context, *connect.Request[v1.GetHealthRequest]) (*connect.Response[v1.GetHealthResponse], error)
	// GetHealthHistory retrieves the audit trail of health transitions.
	GetHealthHistory(context.Context, *connect.Request[v1.GetHealthHistoryRequest]) (*connect.Response[v1.GetHealthHistoryResponse], error)
}

